/**
 * Shader des dunes.
 *
 * ## L'idee mathematique
 *
 * Des cretes superposees : n courbes horizon — un sinus charpente plus un
 * bruit de valeur qui casse sa regularite — empilees du haut vers le bas.
 * Chaque couche recouvre la precedente par un simple seuillage vertical, et
 * derive a sa propre vitesse : c'est la parallaxe qui donne la profondeur,
 * pas un degrade. Les couches basses sont plus claires, comme un sable qui
 * recoit la lumiere rasante.
 *
 * ## Uniforms
 *
 * - `uTime` — temps en secondes, fourni par le moteur.
 * - `uResolution` — taille du canevas en pixels, fournie par le moteur.
 * - `uColorA` — le ciel.
 * - `uColorB` — la crete la plus lointaine.
 * - `uColorC` — la crete la plus proche, la plus claire.
 * - `uSpeed` — vitesse de derive des couches.
 * - `uLayers` — nombre de cretes empilees.
 * - `uAmplitude` — hauteur des ondulations.
 */
export const DUNES_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uSpeed;
uniform float uLayers;
uniform float uAmplitude;

// Nombre pseudo-aleatoire : projection sur une direction arbitraire, sinus
// amplifie, partie fractionnaire.
float duneHash(float p) {
  return fract(sin(p * 127.1) * 43758.5453123);
}

// Bruit de valeur 1D : interpolation lissee entre deux tirages entiers.
float duneNoise(float p) {
  float cell = floor(p);
  float local = fract(p);
  float smoothed = local * local * (3.0 - 2.0 * local);
  return mix(duneHash(cell), duneHash(cell + 1.0), smoothed);
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float x = vUv.x * aspect;
  float t = uTime * uSpeed;
  int couches = int(clamp(uLayers, 2.0, 6.0));

  vec3 colour = uColorA;

  for (int i = 0; i < 6; i += 1) {
    if (i >= couches) break;

    float k = float(i) / max(float(couches) - 1.0, 1.0);

    // Chaque couche descend d'un cran et ralentit : les cretes proches
    // avancent moins que les lointaines, et ce desaccord est la parallaxe.
    float base = 0.78 - k * 0.55;
    float phase = t * (1.2 - 0.9 * k) + float(i) * 4.7;

    // Un sinus pour la charpente, un bruit pour casser sa regularite : le
    // sinus seul ferait une vague mecanique, le bruit seul un trait nerveux.
    float crete = base + uAmplitude * (
      sin(x * 2.1 + phase) * 0.5 +
      (duneNoise(x * 3.7 + phase * 0.6 + float(i) * 13.0) - 0.5) * 1.0
    );

    // Remplissage sous la courbe : la couche recouvre tout ce qui est
    // au-dessous d'elle, avec un bord adouci d'un demi-pour-cent d'ecran.
    float dessous = smoothstep(crete + 0.004, crete - 0.004, vUv.y);

    // Plus proche, plus clair : la teinte de couche va du lointain au rasant.
    vec3 teinte = mix(uColorB, uColorC, k);
    colour = mix(colour, teinte, dessous);
  }

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Dunes : des cretes superposees qui derivent en parallaxe.
 *
 * ## Le principe
 *
 * Des courbes horizon — sinus charpente plus bruit — empilees du haut vers le
 * bas, chacune remplie sous elle par seuillage vertical. Chaque couche est
 * plus claire et plus lente que la precedente : c'est le desaccord des
 * vitesses qui fait la profondeur, pas un degrade.
 *
 * ## Ce que ce composant delegue
 *
 * Il ne porte que ce qui le distingue : son shader, ses reglages et son repli.
 * La lecture des tokens, leur conversion en flottants et leur relecture au
 * changement de theme viennent du moteur — les recopier ici en ferait autant
 * de versions a maintenir qu'il y a de fonds.
 *
 * Le repli n'est pas une precaution : il est affiche pendant le chargement du
 * backend, quand WebGL manque, quand l'arbitre refuse la surface — il n'en
 * accorde qu'une par backend — et sous mouvement reduit.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { DUNES_FRAGMENT } from './dunes.shader.js'

/** Ce que l'echappatoire recoit. */
export interface DunesControls {
  /** Couleurs effectivement transmises au shader. */
  readonly colours: readonly ShaderColour[]
  /** Motif du refus, s'il y en a un. */
  readonly refused: string | undefined
}

/** Proprietes propres au composant. */
export interface DunesOwnProps {
  /** Vitesse de derive des couches. @defaultValue 0.1 */
  speed?: number
  /** Nombre de cretes empilees. @defaultValue 4 */
  layers?: number
  /** Hauteur des ondulations. @defaultValue 0.12 */
  amplitude?: number
  /** Tokens dont les couleurs sont lues. */
  colors?: readonly string[]
  /** Classes du repli. */
  fallback?: string
  /** Echappatoire. */
  onReady?: ReadyCallback<DunesControls>
}

/** Toutes les proprietes. */
export type DunesProps = Customisable<DunesOwnProps>

/** Tokens employes par defaut : le ciel, la crete lointaine, la crete rasante. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-orange-600',
  '--o-palette-amber-300',
] as const

/** Repli par defaut : un degrade fige, dans les memes tons. */
const DEFAULT_FALLBACK =
  'o-bg-gradient-to-b o-from-amber-100 dark:o-from-amber-950 o-to-orange-200 dark:o-to-orange-950'

/**
 * Dunes.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <Dunes className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function Dunes({
  speed = 0.1,
  layers = 4,
  amplitude = 0.12,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: DunesProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: DUNES_FRAGMENT,
    colors,
    uniforms: { uSpeed: speed, uLayers: layers, uAmplitude: amplitude },
    name: 'dunes',
    // Chaque crete est un sinus et un bruit de plus par pixel : c'est le
    // reglage qui pese, donc celui qui est borne.
    degrade: (quality) => ({
      uLayers: quality === 'low' ? Math.min(layers, 3) : layers,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
